//! `IsoVehicle` simulation: wheeled vehicles driven as a rigid chassis plane
//! (`altitude` + `pitch` + `roll`) fit to the four wheel contacts, with each
//! wheel on a per-wheel suspension spring clamped to a travel envelope
//! (compression + droop) and point-mass moon-gravity jumps, driving a body + 4
//! wheel `IsoSprite`s.
//!
//! Part ground-origin anchors come from the vehicle definition sidecar
//! (generated by the Blender exporter).  `spawn_vehicle` derives per-direction
//! wheel tile offsets from those anchors via the engine's iso transform, so
//! parts composite exactly with nothing measured by hand.  `update_vehicles`
//! runs each frame (after the guest update closures) and pushes
//! positions/frames/anchors/offsets into the five sprites.

pub(crate) mod block;
mod control;
mod dust;
mod kinematics;
#[cfg(test)]
mod layer_tests;
pub(crate) mod layers;
mod sim;
mod sockets;
#[cfg(test)]
mod tests;

use classic_core::tilemap::{sample_height_mesh, PPM_TARGET};

pub use kinematics::dir_index;
pub use layers::FIRE_CLIP;

/// Vertical acceleration (metres/s²) — the `40 px/s²` hop re-expressed at
/// `PPM_TARGET` px/m, kept equivalent so the moon-gravity feel is unchanged.
const MOON_GRAVITY: f32 = 40.0 / PPM_TARGET;
/// Per-wheel suspension spring stiffness (per-second²; the same in px and m).
const SUSP_STIFFNESS: f32 = 60.0;
/// Per-wheel suspension damping (1/s).
const SUSP_DAMPING: f32 = 15.0;
/// Upward wheel compression as a fraction of the derived downward droop.  The
/// absolute travel limits are derived per-vehicle from the def geometry at
/// spawn (`spawn_vehicle`): the droop is the vertical reach the baked tilt
/// frames provide at a wheel, and the compression is this fraction of it, so a
/// single-wheel bump compresses the wheel more than it lifts the body.
const COMPRESS_RATIO: f32 = 0.5;

/// A wheel within this height (metres) of its terrain counts as touching it
/// for dust.
const DUST_CONTACT_M: f32 = 0.05;
/// Ground speed (metres/second) at which a dust effect plays as authored:
/// each wheel emitter's `rate` and `speed` multipliers are `speed / REF`.
const DUST_REF_SPEED: f32 = 2.0;
/// Floor of the dust `speed` multiplier, so bursts from a standing start
/// still leave the ground.
const DUST_MIN_SPEED_MUL: f32 = 0.35;
/// Bursts each wheel fires per metre/second of speed change (starting,
/// stopping and speed steps kick up a puff on top of the rate).
const DUST_BURSTS_PER_MPS: f32 = 1.5;
/// How far the dust leans back against the direction of travel (the
/// emission direction is `up − travel · LEAN`, normalized).
const DUST_BACK_LEAN: f32 = 0.6;
/// Landing impact (metres/second) below which no touchdown puff fires.
const TOUCHDOWN_MIN_IMPACT: f32 = 0.3;
/// Impact speed (metres/second) at which the touchdown puff plays at scale 1.
const TOUCHDOWN_REF_IMPACT: f32 = 1.0;

/// Wheel entity-name suffixes, in `[fl, fr, rl, rr]` order (matches the
/// vehicle-definition part order emitted by the exporter).
const WHEEL_SUFFIXES: [&str; 4] = ["Fl", "Fr", "Rl", "Rr"];

/// Body pitch/roll spring stiffness (rad/s² per rad of error).  Kept
/// underdamped (with `SPRING_DAMPING`) so the body bobs with momentum rather
/// than snapping to the terrain.
const SPRING_STIFFNESS: f32 = 40.0;
/// Body pitch/roll spring damping (1/s).
const SPRING_DAMPING: f32 = 8.0;
/// Nose-down pitch target (radians) while the body is airborne (e.g. falling
/// off a cliff).
const AIRBORNE_PITCH: f32 = -0.26;

/// Distance from the final waypoint (in tiles) at which the pure-pursuit
/// follower considers the goal reached and stops.
const GOAL_TOLERANCE: f32 = 0.5;
/// A pose route's turning radius over the follower's own (`speed /
/// turn_rate`): room for the steering lag and the pursuit's corner cutting.
const POSE_TURN_MARGIN: f32 = 1.3;
/// A pose route's cost multiplier for a backward tile.
const POSE_REVERSE_COST: f32 = 2.0;

/// Cost multiplier for a downward "jump" step in A* (`>= 1.0`).  A mild
/// penalty makes the vehicle prefer flat routes but take a jump when it
/// clearly shortens the path.
const JUMP_COST: f32 = 1.3;

/// Heading error (radians) above which a `pivot_turn` (tracked) vehicle
/// stops and turns in place instead of arcing.
const PIVOT_TURN_ENTER: f32 = 30.0f32.to_radians();

/// Heading error (radians) above which the vehicle shifts into reverse to
/// reorient rather than arcing forward off-traversable.
const REVERSE_ENTER: f32 = 100.0f32.to_radians();
/// Heading error (radians) below which the vehicle shifts back to forward
/// (hysteresis around [`REVERSE_ENTER`]).
const REVERSE_EXIT: f32 = 70.0f32.to_radians();

/// The outcome of submitting a vehicle path request via [`Engine::vehicle_goto`].
pub enum VehicleGotoSubmit {
    /// Vehicle is airborne; the guest should re-issue next frame.
    Airborne,
    /// No entity with that name (drop the request).
    NoVehicle,
    /// Request submitted; poll with [`Engine::vehicle_goto_poll`].
    Submitted(u64),
}

/// The outcome of polling a vehicle path request via [`Engine::vehicle_goto_poll`].
pub enum VehicleGotoPoll {
    /// The search is still running.
    Pending,
    /// A route was found; carries the waypoints to install on the vehicle.
    Accepted(Vec<[i32; 2]>),
    /// No route exists (drop the request).
    NoPath,
}

/// The state of the single in-flight (or cached) non-mutating reachability
/// probe tracked by [`Engine::vehicle_probe`].  The result is cached per target
/// so an unchanged probe target doesn't re-run A* every frame.
pub struct PreviewProbe {
    pub name: String,
    pub target: (i32, i32),
    pub state: PreviewProbeState,
}

/// The in-flight/cached phase of a [`PreviewProbe`].
#[derive(Clone, Copy)]
pub enum PreviewProbeState {
    /// Search running on the worker; poll `id` via `poll_vehicle_path`.
    Pending { id: u64 },
    /// Search finished; `reachable` is the cached answer.
    Done { reachable: bool },
}

/// A terrain-height sampler snapshot, cloned once per frame so the mutation
/// pass can sample heights without re-borrowing the world.
struct TerrainSnapshot {
    size_x: i32,
    size_y: i32,
    heights: Vec<f32>,
    /// Raised floors (`set_floor_rect`).
    floors: Vec<crate::floor::FloorRect>,
}

impl TerrainSnapshot {
    /// Terrain height in **world metres** (the unit the vehicle sim now lives
    /// in): the reference of every `frame_offset` altitude (the sprite model
    /// re-adds it).
    fn height(&self, x: f32, y: f32) -> f32 {
        sample_height_mesh(&self.heights, self.size_x, self.size_y, x, y)
    }

    /// The ground a wheel stands on: the terrain raised to any floor rect.
    fn ground(&self, x: f32, y: f32) -> f32 {
        crate::floor::ground_height(&self.floors, self.height(x, y), x, y)
    }
}

/// The values pushed into the body + wheel sprites each frame.
struct VehicleWrite {
    body: [f32; 3],
    /// The vehicle's direction count.
    directions: u32,
    /// A v2 (layered) vehicle: `apply_layers` frames the body.
    layered: bool,
    /// Body lift above its own terrain in **world metres** (`frame_offset.z`).
    body_altitude: f32,
    body_anchor: [f32; 2],
    direction: u32,
    body_frame: f32,
    wheel_xy: [[f32; 2]; 4],
    /// Per-wheel lift above its terrain in **world metres** (`frame_offset.z`).
    wheel_altitude: [f32; 4],
    wheel_z: [f32; 4],
    wheel_anchors: [[f32; 2]; 4],
    steer_index: u32,
    /// Body heading (tile-space radians).
    heading: f32,
    /// `+1` driving forward, `-1` reversing, `0` stopped.
    motion_sign: f32,
    /// Ground speed this frame (metres/second).
    speed_mps: f32,
    /// `|Δ ground speed|` since last frame (metres/second).
    dspeed_mps: f32,
    /// Per-wheel ground contact (within [`DUST_CONTACT_M`] of the terrain).
    grounded: [bool; 4],
    /// Impact speed (metres/second) on the frame the body lands, if it did.
    touchdown: Option<f32>,
}
